@verbatim<script>(function(){var h=[],st='',box=document.getElementById('sim'),tr=document.getElementById('simTr'),inp=document.getElementById('simIn'),tok=document.querySelector('input[name=_token]').value;
function add(r,t){var d=document.createElement('div');d.style.cssText='margin:4px 0;'+(r==='user'?'text-align:right;color:#1D5FA8':'color:#0B1220');d.textContent=(r==='user'?'গ্রাহক: ':'AI: ')+t;box.appendChild(d);box.scrollTop=box.scrollHeight}
document.getElementById('simGo').onclick=function(){var t=inp.value.trim();if(!t)return;inp.value='';h.push({role:'user',content:t});add('user',t);
fetch('/admin/ai-chat/simulate',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':tok,'Accept':'application/json'},body:JSON.stringify({messages:h,state:st,orders:document.getElementById('simOrd').checked})}).then(function(r){return r.json()}).then(function(j){if(j.error&&!j.reply){add('assistant','[error] '+j.error);return}h.push({role:'assistant',content:j.reply});st=j.state||'';add('assistant',j.reply);tr.textContent=(j.tools||[]).map(function(x){return x.tool+' '+JSON.stringify(x.input)+'\n  -> '+JSON.stringify(x.result).slice(0,300)}).join('\n')})};
inp.addEventListener('keydown',function(e){if(e.key==='Enter')document.getElementById('simGo').click()})})();</script>@endverbatim
